function liveCounts(){const inside=leads.filter(l=>RTCRM.visible(l)&&l.scope==='inside'&&l.role!=='Competition reference');return {...D.review.counts,inside:inside.length,inside_relevant:inside.filter(l=>l.fit_group!=='Exploratory').length,inside_exploratory:inside.filter(l=>l.fit_group==='Exploratory').length,pending:leads.filter(l=>RTCRM.visible(l)&&l.scope==='pending'&&l.role!=='Competition reference').length}}
const columnDefs=[{id:'name',title:'Place / organisation',width:285},{id:'photo',title:'Photo',width:155},{id:'level',title:'Manual level',width:135},{id:'contact',title:'Contact coverage',width:230},{id:'distance',title:'Distance / address',width:240},{id:'type',title:'Type / relevance',width:200},{id:'channels',title:'Research channels',width:220},{id:'note',title:'My notes',width:270},{id:'action',title:'状态 / Status',width:220},{id:'evidence',title:'Demand evidence',width:290}];
let tablePrefs;try{tablePrefs=JSON.parse(localStorage.getItem('rt-table-preferences')||'{}')}catch{tablePrefs={}}
const columns=[...new Set([...(tablePrefs.order||[]),...columnDefs.map(c=>c.id)])].filter(k=>columnDefs.some(c=>c.id===k));
let colOrder=columns,colWidths=tablePrefs.widths||{},colHidden=new Set(tablePrefs.hidden||[]),sortBy=tablePrefs.sortBy||'distance',sortDir=tablePrefs.sortDir||1,detailDirty=false;
function persistTable(){try{localStorage.setItem('rt-table-preferences',JSON.stringify({order:colOrder,widths:colWidths,hidden:[...colHidden],sortBy,sortDir}))}catch{}}
function workspaceStatus(){$('workspace-status').innerHTML=!RTCRM.ready?`<div class="notice">Online records could not be loaded. Leads are paused to avoid showing excluded addresses. <button id="reload-workspace">Retry</button></div>`:RTCRM.canEdit?`<p class="workspace-state">已同步</p>`:`<p class="workspace-state"><a href="/signin-with-chatgpt?return_to=${encodeURIComponent(location.pathname+location.search)}" target="_top">登录管理</a></p>`;if($('reload-workspace'))$('reload-workspace').onclick=async()=>{await RTCRM.load();render()}}
function filtered(){RTCRM.apply(leads);if(!RTCRM.ready)return [];return baseFiltered().filter(l=>RTCRM.visible(l)&&(section==='Clients'?RTFlow.status(l)==='client':section==='Followup'?['follow','hold','giveup'].includes(RTFlow.status(l)):section==='Leads'?RTFlow.status(l)==='new':true)&&(!$('level').value||RTCRM.get(l.id).level===+$('level').value)&&(!$('coverage').value||($('coverage').value==='none'?RTCRM.completeness(l)===0:$('coverage').value==='direct'?RTCRM.routes(l).slice(0,2).some(x=>x.url):RTCRM.completeness(l)>0)))}
function contacts(l){const routes=RTCRM.routes(l),n=RTCRM.completeness(l);return `<div class="contact-icons">${routes.map(r=>r.url?`<a class="contact-icon" title="${esc(r.name)} · available, not independently reconfirmed" aria-label="${esc(r.name)} available" href="${esc(r.url.startsWith('mailto:')||r.url.startsWith('tel:')?r.url:safeURL(r.url))}" target="_blank" rel="noopener">${r.icon}</a>`:`<span class="contact-icon missing" title="${r.name} · not collected" aria-label="${r.name} missing">${r.icon}</span>`).join('')}</div><small class="${n?'':'no-contact'}">${n}/7 routes · ${n?'已收录':'暂无联系入口'}</small>`}
function photo(l,large=false){const pics=l.photos||[];return pics.length?`<div class="${large?'photo-gallery':'photo-thumb'}">${pics.slice(0,large?8:1).map(p=>`<figure><a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(safeURL(p.url))}" alt="${esc(p.caption)}" referrerpolicy="no-referrer"></a>${large?`<figcaption>${anchor(p.source_url,'Photo source')}<small>${esc(p.verification)}</small></figcaption>`:''}</figure>`).join('')}</div>`:`<div data-photo="${esc(l.id)}" data-large="${large}"><div class="photo-missing">▧<small>Looking for a matching place photo…</small></div></div>`}
function card(l){const m=RTCRM.get(l.id);return `<article class="card">${photo(l)}<button class="name" data-id="${esc(l.id)}">${esc(l.name)}</button>${RTCRM.star(l.id)}<small>${esc(dist(l))} · ${esc(l.address)}</small>${tags(l)}${contacts(l)}<div class="bilingual"><p lang="zh-CN">${esc(l.profile_summary?.[0]?.body.zh||l.name)}</p><p lang="en">${esc(l.profile_summary?.[0]?.body.en||l.name)}</p></div>${m.note?`<p class="saved-note">${esc(m.note)}</p>`:''}${RTFlow.actions(l)}${m.action?`<small>Recorded action: ${esc(m.action)}</small>`:''}</article>`}
function sortValue(l,k){const m=RTCRM.get(l.id);return ({name:l.name,photo:l.photos?.length||0,level:m.level||99,contact:RTCRM.completeness(l),distance:l.distance_km??99999,type:l.type,channels:Object.keys(l.channels).join(' '),note:m.note,action:m.follow,evidence:l.fact})[k]}
function cell(l,k){const m=RTCRM.get(l.id);return ({name:`<button class="name" data-id="${esc(l.id)}">${esc(l.name)}</button><small>${esc(l.role)}</small>`,photo:`${photo(l)}<button class="photo-open" data-id="${esc(l.id)}" aria-label="Open ${esc(l.name)} photos">View photos</button>`,level:`<button class="level-open" data-id="${esc(l.id)}" title="Edit manual level">${RTCRM.star(l.id)}</button>`,contact:contacts(l),distance:`<strong>${esc(dist(l))}</strong><small>${esc(l.address)}</small>`,type:tags(l),channels:channelTags(l),note:`<button class="note-open" data-id="${esc(l.id)}">${m.note?esc(m.note):'＋ Add note'}</button>`,action:`${RTFlow.badge(l)}<button data-id="${esc(l.id)}">更改状态</button><small>${esc(m.action)}</small>`,evidence:`${l.signal?`<span class="tag">${esc(l.signal)}</span>`:'No court demand verified'}<small>${esc(l.fact)}</small>`})[k]}
function table(ls){const visible=colOrder.filter(k=>!colHidden.has(k));const sorted=[...ls].sort((a,b)=>{const x=sortValue(a,sortBy),y=sortValue(b,sortBy);return sortDir*(typeof x==='number'?x-y:String(x).localeCompare(String(y)))||a.name.localeCompare(b.name)});return `<div class="table-tools"><details><summary>Columns · show / hide / order</summary><div class="column-settings">${colOrder.map(k=>`<div><label><input type="checkbox" data-column="${k}" ${colHidden.has(k)?'':'checked'}>${columnDefs.find(c=>c.id===k).title}</label><button data-move="${k}" data-direction="-1" aria-label="Move ${k} left">←</button><button data-move="${k}" data-direction="1" aria-label="Move ${k} right">→</button></div>`).join('')}</div></details><span>Click header to sort · Drag headers to reorder · Drag edges to resize · First visible column and header frozen</span></div><div class="tablewrap editable-table"><table style="width:${visible.reduce((s,k)=>s+(colWidths[k]||columnDefs.find(c=>c.id===k).width),0)}px"><colgroup>${visible.map(k=>`<col data-col="${k}" style="width:${colWidths[k]||columnDefs.find(c=>c.id===k).width}px">`).join('')}</colgroup><thead><tr>${visible.map(k=>`<th draggable="true" data-head="${k}" aria-sort="${sortBy===k?(sortDir===1?'ascending':'descending'):'none'}"><button data-sort="${k}">${columnDefs.find(c=>c.id===k).title} ${sortBy===k?(sortDir===1?'↑':'↓'):''}</button><span class="resize-handle" role="separator" tabindex="0" aria-label="Resize ${k}; use arrow keys" data-resize="${k}"></span></th>`).join('')}</tr></thead><tbody>${sorted.map(l=>`<tr>${visible.map(k=>`<td>${cell(l,k)}</td>`).join('')}</tr>`).join('')}</tbody></table>${ls.length?'':'<div class="empty">No matching leads.</div>'}</div>`}
function redrawTable(){const open=document.querySelector('.table-tools details')?.open;render();if(open&&document.querySelector('.table-tools details'))document.querySelector('.table-tools details').open=true}
function bindWorkspace(){
 RTPhotos.bind(leads);RTFlow.bindActions();
 document.querySelectorAll('img').forEach(img=>img.onerror=()=>{const box=document.createElement('div');box.className='photo-missing';box.textContent='Source photo unavailable';img.replaceWith(box)});
 document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const m=RTCRM.get(b.dataset.follow);await RTCRM.save(b.dataset.follow,{level:m.level,note:m.note,action:m.action,follow:!m.follow});render()}catch(e){b.disabled=false;alert(e.message)}});
 document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sortDir=sortBy===b.dataset.sort?-sortDir:1;sortBy=b.dataset.sort;persistTable();redrawTable()});
 document.querySelectorAll('[data-column]').forEach(b=>b.onchange=()=>{if(!b.checked&&colOrder.length-colHidden.size<=1){b.checked=true;return}b.checked?colHidden.delete(b.dataset.column):colHidden.add(b.dataset.column);persistTable();redrawTable()});
 function move(k,index){colOrder=colOrder.filter(x=>x!==k);colOrder.splice(Math.max(0,Math.min(index,colOrder.length)),0,k);persistTable();redrawTable()}
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move,colOrder.indexOf(b.dataset.move)+ +b.dataset.direction));
 let dragged=null;document.querySelectorAll('[data-head]').forEach(h=>{h.ondragstart=e=>{if(e.target.closest('.resize-handle')){e.preventDefault();return}dragged=h.dataset.head;e.dataTransfer.setData('text/plain',dragged)};h.ondragover=e=>e.preventDefault();h.ondrop=e=>{e.preventDefault();if(dragged)move(dragged,colOrder.indexOf(h.dataset.head));dragged=null}});
 document.querySelectorAll('[data-resize]').forEach(h=>{const k=h.dataset.resize;const resize=w=>{colWidths[k]=Math.max(90,Math.min(650,w));document.querySelector(`[data-col="${k}"]`).style.width=colWidths[k]+'px';const t=document.querySelector('.editable-table table');t.style.width=colOrder.filter(x=>!colHidden.has(x)).reduce((s,x)=>s+(colWidths[x]||columnDefs.find(c=>c.id===x).width),0)+'px'};h.onpointerdown=e=>{e.preventDefault();e.stopPropagation();const x=e.clientX,w=colWidths[k]||columnDefs.find(c=>c.id===k).width;h.parentElement.draggable=false;h.setPointerCapture(e.pointerId);h.onpointermove=ev=>resize(w+ev.clientX-x);h.onpointerup=()=>{h.onpointermove=null;h.parentElement.draggable=true;persistTable()}};h.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();resize((colWidths[k]||columnDefs.find(c=>c.id===k).width)+(e.key==='ArrowRight'?20:-20));persistTable()}}});
}
function openDetail(id){if(detailDirty&&!confirm('Discard unsaved changes?'))return;detailDirty=false;baseOpenDetail(id);const l=leads.find(x=>x.id===id);if(!l||!RTCRM.visible(l)){if($('detail').open)$('detail').close();return}const m=RTCRM.get(id),box=document.createElement('section');box.className='management';box.innerHTML=`<h3>我的记录</h3>${contacts(l)}<form id="lead-editor"><label>Manual level<select id="edit-level" ${RTCRM.canEdit?'':'disabled'}>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${m.level===n?'selected':''}>${n?['','★ L1 · Red · Highest','★ L2 · Orange','★ L3 · Yellow','★ L4 · Green','★ L5 · Blue · Lowest'][n]:'未评级'}</option>`).join('')}</select></label><label>评注<textarea id="edit-note" rows="4" maxlength="10000" ${RTCRM.canEdit?'':'disabled'} placeholder="Your assessment, contact details to check, or next step">${esc(m.note)}</textarea></label><label>接洽记录<textarea id="edit-action" rows="2" maxlength="2000" ${RTCRM.canEdit?'':'disabled'} placeholder="Only record completed work, e.g. email sent on 14 Sep; include result or reference">${esc(m.action)}</textarea></label><small>新接洽记录会进入 Followup。</small><div class="row-actions"><button type="submit" ${RTCRM.canEdit?'':'disabled'}>保存</button></div><p id="save-status" role="status">${m.updated?'Last saved '+esc(new Date(m.updated).toLocaleString()):RTCRM.canEdit?'':'登录后编辑'}</p></form><h3>Place photos</h3>${photo(l,true)}${l.photos?.length?`<h4>Additional Google place photos</h4><div data-photo="${esc(l.id)}" data-large="true">Looking for a matching listing…</div>`:''}`;$('detailbody').insertBefore(box,$('detailbody').children[1]);
 $('lead-editor').oninput=()=>detailDirty=true;
 $('lead-editor').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const action=$('edit-action').value,values={level:+$('edit-level').value,note:$('edit-note').value,action,follow:m.status==='follow'||(m.status==='new'&&action.trim()!==m.action.trim()&&!!action.trim())};try{await RTCRM.save(id,values);detailDirty=false;render();openDetail(id);$('save-status').textContent='Saved online.'}catch(e){$('save-status').textContent=e.message;button.disabled=false}};
 if($('exclude-lead'))$('exclude-lead').onclick=async()=>{const reason=prompt('Permanently exclude this entire address from all views and future imports, including other organisations at the same address. Enter a reason:');if(!reason?.trim())return;const button=$('exclude-lead');button.disabled=true;try{await RTCRM.remove(l,reason);detailDirty=false;$('detail').close();render()}catch(e){$('save-status').textContent=e.message;button.disabled=false}};
 RTDetail.mount(l);bindWorkspace();
}
const originalMapView=mapView;
mapView=function(ls){return `<div class="star-legend">${[1,2,3,4,5].map(n=>`<span style="color:${RTCRM.colors[n]}">★ L${n} · ${ls.filter(l=>RTCRM.get(l.id).level===n).length}</span>`).join('')}<small>L1 高 → L5 低</small></div>`+originalMapView(ls)};
$('detail').addEventListener('cancel',e=>{if(detailDirty&&!confirm('Discard unsaved changes?'))e.preventDefault();else detailDirty=false});
window.addEventListener('beforeunload',e=>{if(detailDirty){e.preventDefault();e.returnValue=''}});
init().then(()=>{$('close').onclick=()=>{if(!detailDirty||confirm('Discard unsaved changes?')){detailDirty=false;$('detail').close()}}});

window.addEventListener('focus',async()=>{const before=RTCRM.canEdit;await RTCRM.load();if(before!==RTCRM.canEdit){render();if($('detail').open)openDetail($('detail').dataset.id)}});
